<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import IconGraphic from "./icon-graphic";
import Switch from "../v-switch/v-switch.vue";
import { IconShape, IconShapeValues } from "./icon.constants";
import { has } from "../../util/has";
import { Fragment } from "vue-fragment";

@Component({
  components: {
    IconGraphic,
    "v-switch": Switch,
    Fragment,
  },
})
export default class Icon extends Vue {
  /** The selected icon shape to render */
  @Prop({
    type: Number,
    default: IconShape.SEARCH,
    validator: has(IconShapeValues),
  })
  shape;
  /**
   * The size of the icon. A single number will cause the icon to max out on
   * width OR height at that size and maintain aspect ration. You can specify an
   * object too with { width }, { height }, { width, height }. If you specify a
   * single dimension it will scale up the icon to fit that dimension but
   * maintain aspect ratio. If you specify both, then you get those exact
   * dimensions and aspect ratio will be ignored.
   */
  @Prop({ type: [Number, Object], default: () => ({ height: 24 }) }) size;
  /** Specifies the color of the icon */
  @Prop({ type: String, default: undefined }) color;

  /** Used internally as a handoff from icon graphics */
  baseSize = { width: 10, height: 10 };
  renderWidth = 10;
  renderHeight = 10;

  get iconColor() {
    return this.color;
  }

  get iconShape() {
    return this.shape;
  }

  get IconShape() {
    return IconShape;
  }

  get viewBox() {
    return `0 0 ${this.baseSize.width} ${this.baseSize.height}`;
  }

  handleClick() {
    /**
     * Emits when the icon is clicked
     *
     * @event click
     */
    this.$emit("click");
  }
}
</script>

